```javascript
const cards = [...document.querySelectorAll(".card")];
const heights = cards.map((card) => card.getBoundingClientRect().height);
const tallest = Math.max(0, ...heights);

for (const card of cards) {
  card.style.minHeight = `${tallest}px`;
}
```
